def find_seeds(grid):
    """Find positions of all special values (non-background)."""
    special_positions = {}
    background = grid[0][0]  # background is typically the most common value
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                if c not in special_positions:
                    special_positions[c] = []
                special_positions[c].append((r, grid[r][c]))
    return special_positions, background

